def dedup_report(rows, key_fn):
    seen, unique, conflicts = {}, [], []
    for row in rows:
        key = key_fn(row)
        if key not in seen:
            seen[key] = row
            unique.append(row)
        elif seen[key] != row:
            conflicts.append({'key': key, 'kept': seen[key], 'other': row})
    return {'unique': unique, 'conflicts': conflicts}

